<script setup lang="ts">
import { useI18n } from 'vue-i18n'
import type { Bilingual, StoryNode, StoryState } from '../api/story'
defineProps<{ node: StoryNode; state: StoryState; busy: boolean; bilingual: boolean }>()
defineEmits<{ act: [action: string, answer?: string]; refresh: [] }>()
const { locale } = useI18n()
const words = (zh: string, en: string) => locale.value === 'en' ? en : zh
const primary = (value?: Bilingual) => value ? locale.value === 'en' ? value.en || value.zh : value.zh || value.en : ''
const secondary = (value?: Bilingual) => value ? locale.value === 'en' ? value.zh : value.en : ''
</script>
<template>
  <section class="dual-panel"><div class="clue-heading"><span class="perspective-token">{{ state.perspective || 'A' }}</span><div><p class="eyebrow">TWO PERSPECTIVES · ONE STORY</p><h3>{{ words('你的一半线索', 'Your half of the story') }}</h3></div></div><div class="clue-paper"><p class="small-label">{{ words('你的专属线索', 'YOUR PRIVATE CLUE') }}</p><p>{{ primary(node.clue) }}</p><p v-if="bilingual" class="parallel-text">{{ secondary(node.clue) }}</p></div><div class="dual-partner-note"><span class="privacy-mark" aria-hidden="true">◇</span><p>{{ words('另一半，由同行者保管。等待期间，对方的线索与答案不会在这里展开。', 'The other half belongs to your companion. Their clue and answer stay private while you wait.') }}</p></div><p class="dual-status" data-testid="dual-status" role="status">{{ state.dual?.state === 'TIMEOUT' ? words('协作窗口已结束，仍可补交。', 'The window has expired; late submissions are accepted.') : state.dual?.submitted ? words('已提交，等待另一位伙伴。', 'Submitted. Waiting for your partner.') : words('请选择并提交自己的判断。', 'Select and submit your own answer.') }}</p><p v-if="state.dual" class="dual-deadline">{{ words('协作截止', 'Collaboration deadline') }} <time :datetime="state.dual.deadline">{{ new Date(state.dual.deadline).toLocaleString(locale === 'en' ? 'en-US' : 'zh-CN') }}</time></p><div v-if="!state.dual?.submitted" class="story-options"><button v-for="option in node.options" :key="option.id" class="story-option" :data-testid="`answer-${option.id}`" :disabled="busy" @click="$emit('act', 'submit', option.id)"><span>{{ primary(option.label) }}</span><small v-if="bilingual">{{ secondary(option.label) }}</small></button></div><div v-if="state.dual?.state === 'TIMEOUT'" class="story-actions"><button v-if="!state.dual.extended" class="secondary-button" :disabled="busy" @click="$emit('act', 'extend')">{{ words('延长48小时', 'Extend by 48 hours') }}</button><button class="secondary-button" :disabled="busy" @click="$emit('act', 'script')">{{ words('切换脚本伙伴', 'Switch to script companion') }}</button><button class="text-button" :disabled="busy" @click="$emit('act', 'skip')">{{ words('跳过，不加默契', 'Skip without harmony points') }}</button></div><div class="dual-sync"><button class="text-button" :disabled="busy" @click="$emit('refresh')">{{ words('刷新协作状态', 'Refresh collaboration') }} ↻</button><small>{{ state.partnerMode === 'HUMAN' ? words('每4秒同步 · 答案提交后自动存档', 'Syncs every 4 seconds · Answers are saved') : words('脚本伙伴 · 由服务端判定', 'Script companion · Server-validated') }}</small></div></section>
</template>
